    source: "CNA",
    url: "https://www.channelnewsasia.com/east-asia/south-korea-foreign-minister-china-cooperation-6551271",
    time: "11 ore fa",
    pub_ts: 1794633366,
    published_at: "2026-11-14T05:16:06+00:00",
